-- Create a savepoint and use TCL/DCL logic
CREATE TABLE accounts (id INT, balance DECIMAL);

-- DCL: Granting permissions
GRANT SELECT, UPDATE ON accounts TO app_user;

-- TCL: Managing transactions
BEGIN TRANSACTION;
INSERT INTO accounts VALUES (1, 1000.00);
SAVEPOINT before_update;

UPDATE accounts SET balance = balance - 500 WHERE id = 1;
-- Oops, let's rollback to savepoint if error occurs
ROLLBACK TO before_update;

-- Commit the valid transaction
COMMIT;

