-- Example: Students (PK student_id) and LibraryCards (PK card_id)
-- 1:1 total participation (every student must have a card)
CREATE TABLE Students (
    student_id INT PRIMARY KEY,
    name VARCHAR(50) NOT NULL
);

CREATE TABLE LibraryCards (
    card_id INT PRIMARY KEY,
    student_id INT UNIQUE NOT NULL, -- UNIQUE enforces 1:1, NOT NULL enforces total
    issue_date DATE,
    FOREIGN KEY (student_id) REFERENCES Students(student_id)
);

-- Example: Teachers (PK teacher_id) and Classes (PK class_id)
-- 1:N participation (one teacher can teach many classes, each class has exactly one teacher)
CREATE TABLE Teachers (
    teacher_id INT PRIMARY KEY,
    name VARCHAR(50)
);

CREATE TABLE Classes (
    class_id INT PRIMARY KEY,
    teacher_id INT NOT NULL, -- total participation for Classes
    subject VARCHAR(30),
    FOREIGN KEY (teacher_id) REFERENCES Teachers(teacher_id)
);

-- Example: Students and Books (M:N)
-- Junction table Student_Book captures many‑to‑many borrowing relationship
