-- Unnormalized schema with repeating groups:
-- CREATE TABLE Employees (EmpID INT, Name VARCHAR(50), Skills VARCHAR(100));

-- 1NF Compliant Schema (Atomic values per row):
CREATE TABLE EmployeeSkills (
    EmpID INT,
    EmpName VARCHAR(50),
    Skill VARCHAR(50),
    PRIMARY KEY (EmpID, Skill)
);

