-- Violation of 2NF (StudentName depends only on StudentID, part of composite key):
-- TABLE Enrollment(StudentID, CourseID, StudentName, Grade);

-- 2NF Compliant Schema:
CREATE TABLE Students (
    StudentID INT PRIMARY KEY,
    StudentName VARCHAR(50)
);

CREATE TABLE CourseEnrollments (
    StudentID INT,
    CourseID INT,
    Grade CHAR(2),
    PRIMARY KEY (StudentID, CourseID),
    FOREIGN KEY (StudentID) REFERENCES Students(StudentID)
);

INSERT INTO Students VALUES (101, 'Bob');
INSERT INTO CourseEnrollments VALUES (101, 301, 'A');
SELECT * FROM CourseEnrollments;

-- Violation of 3NF (EmpID -> DeptID -> DeptName):
-- TABLE Employees(EmpID, EmpName, DeptID, DeptName);

-- 3NF Compliant Schema:
CREATE TABLE Departments (
    DeptID INT PRIMARY KEY,
    DeptName VARCHAR(50)
);

CREATE TABLE Employees3NF (
    EmpID INT PRIMARY KEY,
    EmpName VARCHAR(50),
    DeptID INT,
    FOREIGN KEY (DeptID) REFERENCES Departments(DeptID)
);

INSERT INTO Departments VALUES (10, 'AI Research');
INSERT INTO Employees3NF VALUES (1, 'Charlie', 10);
SELECT e.EmpID, e.EmpName, d.DeptName FROM Employees3NF e JOIN Departments d ON e.DeptID = d.DeptID;

