-- 4NF Example: Decomposing a table with multiple independent multivalued attributes
-- Original unnormalized table: Employee(EmpID, Skill, Language)

-- Step 1: Create separate tables to eliminate MVD (EmpID ->> Skill and EmpID ->> Language)
CREATE TABLE Employee_Skills (
    EmpID INT,
    Skill VARCHAR(50),
    PRIMARY KEY (EmpID, Skill)
);

CREATE TABLE Employee_Languages (
    EmpID INT,
    Language VARCHAR(50),
    PRIMARY KEY (EmpID, Language)
);

-- Inserting normalized data prevents Cartesian product explosion
INSERT INTO Employee_Skills VALUES (1, 'Python'), (1, 'SQL');
INSERT INTO Employee_Languages VALUES (1, 'English'), (1, 'Spanish');

-- Example schema checking dependency preservation concept
-- Original Relation: R(A, B, C) with FDs: F = {A -> B, B -> C}
-- Decomposed into: R1(A, B) and R2(B, C)

-- In R1, FD 'A -> B' is preserved (both A and B are in R1)
CREATE TABLE R1 (
    A INT PRIMARY KEY,
    B INT
);

-- In R2, FD 'B -> C' is preserved (both B and C are in R2)
CREATE TABLE R2 (
    B INT PRIMARY KEY,
    C INT
);

-- Since all FDs from F are locally checkable in R1 or R2, the decomposition is dependency-preserving.

-- Lossless-join verification example
-- Relation R(A, B, C) with FD: A -> BC
-- Decomposed into R1(A, B) and R2(A, C)
-- Intersection: R1 ∩ R2 = {A}
-- Since A -> B (from A -> BC), A is a key for R1(A, B).

CREATE TABLE Employees_Dept (
    EmpID INT PRIMARY KEY,
    DeptName VARCHAR(50)
);

CREATE TABLE Employees_Email (
    EmpID INT PRIMARY KEY,
    Email VARCHAR(100)
);

-- Natural join reconstructs the original relation perfectly without spurious rows:
SELECT * FROM Employees_Dept D
JOIN Employees_Email E ON D.EmpID = E.EmpID;

-- Example of a concurrent schedule using two transactions
-- T1: transfer $100 from account A to B
-- T2: read total balance of A and B
BEGIN TRANSACTION T1;
    UPDATE accounts SET balance = balance - 100 WHERE acc_id = 'A'; -- W1(A)
    UPDATE accounts SET balance = balance + 100 WHERE acc_id = 'B'; -- W1(B)
COMMIT;

BEGIN TRANSACTION T2;
    SELECT balance FROM accounts WHERE acc_id = 'A'; -- R2(A)
    SELECT balance FROM accounts WHERE acc_id = 'B'; -- R2(B)
COMMIT;
-- The interleaving of W1(A) and R2(A) creates a conflict; proper locking prevents dirty reads.

