/* Pseudocode solution */
class LockManager:
    def __init__(self):
        self.locks = {}          # item -> (mode, holder list)
        self.waits = {}          # txn -> set of txns it waits for
    def request(self, txn, item, mode):
        if item not in self.locks:
            self.locks[item] = (mode, [txn])
            return 'granted'
        cur_mode, holders = self.locks[item]
        if mode == 'S' and cur_mode == 'S':
            holders.append(txn); return 'granted'
        # conflict
        self.waits.setdefault(txn, set()).update(holders)
        if self._has_cycle(txn):
            self.waits[txn].remove(holders[0])
            return 'deadlock'
        return 'wait'
    def _has_cycle(self, start, visited=None):
        if visited is None: visited = set()
        if start in visited: return True
        visited.add(start)
        for nxt in self.waits.get(start, []):
            if self._has_cycle(nxt, visited):
                return True
        visited.remove(start)
        return False

